// NormalizeSupplierName takes a supplier name and returns the standardized version.
// If the name is not in the mapping, it returns the original name.
func NormalizeSupplierName(name string) string {
	if normalized, exists := SupplierNameCases[name]; exists {
		return normalized
	}
	return name
}
